fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    assert!(a.len() <= 100, "Length must be at most 100");

    let mut c: Vec<u32> = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        c.push(a[i] * b[i]);
    }
    c
}